    /**
     * Tests creating a new User.
     *
     * @return    User
     */
    public User testCreate() throws Throwable {
    User entity = null;

    LOGGER.info( "UserTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a User");

    StringBuilder msg = new StringBuilder( "-- Failed to create a User" );

    try {
        entity = service.createUser( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getUserId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a User with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

    /**
     * Tests reading a User.
     *
     * @return    User
     */
    public User testRead() throws Throwable {
    LOGGER.info( "UserTest:testRead()" );
    LOGGER.info( "-- Reading a previously created User" );

    User entity = null;
    StringBuilder msg = new StringBuilder( "-- Failed to read User with primary key" );
    msg.append( theId );

    try {
        entity = service.getUser( new UserFetchOneSummary(theId) );

        assertNotNull( entity,msg.toString() );

        // for use later
        theId = entity.getUserId();

        LOGGER.info( "-- Successfully found User " + entity.toString() );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + " : " + e );

        throw e;
    }

    return( entity );
}

    /**
     * Tests updating a User.
     *
     * @return    User
     */
    public User testUpdate() throws Throwable {
    LOGGER.info( "UserTest:testUpdate()" );
    LOGGER.info( "-- Attempting to update a User." );

    StringBuilder msg = new StringBuilder( "Failed to update a User : " );
    User entity = null;

    try {
        UpdateUserCommand updateCommand = this.generateUpdateCommand();

        // apply the current id as to update the fields of the current entity
        updateCommand.setUserId( theId );

        assertNotNull( updateCommand, msg.toString() );

        LOGGER.info( "-- Now updating the created User." );

        entity = service.updateUser( updateCommand );

        assertNotNull( entity, msg.toString()  );

        LOGGER.info( "-- Successfully saved User - " + entity.toString() );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + " : primarykey-" + theId + " : entity-" +  entity + " : " + e );

        throw e;
    }

    return( entity );
}

    /**
     * Tests deleting a User.
     */
    public void testDelete() throws Throwable {
    LOGGER.info( "UserTest:testDelete()" );
    LOGGER.info( "-- Deleting a previously created User." );

    try {
        DeleteUserCommand deleteCommand = new DeleteUserCommand( theId );

        service.delete( deleteCommand );

        LOGGER.info( "-- Successfully deleted User with primary key " + theId );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( "-- Failed to delete User with primary key " + theId );

        throw e;
    }
}

    /**
     * Tests getting all Users.
     *
     * @return    Collection
     */
    public List<User> testGetAll() throws Throwable {
    LOGGER.info( "UserTest:testGetAll() - Retrieving Collection of Users:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all User : " );
    List<User> collection  = null;

    try {
        // call the static get method on the UserService
        collection = service.getAllUser();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            User currEntity  = null;
            Iterator<User> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getUserId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

